import React, { useState, useEffect } from 'react';
import api from '../api/axios';
import { Container, Table, Form, Button, Alert, Modal } from 'react-bootstrap';

const ClassManager = () => {
  const [classes, setClasses] = useState([]);
  const [teachers, setTeachers] = useState([]);
  const [showModal, setShowModal] = useState(false);
  const [newClass, setNewClass] = useState({
    grade: 1,
    teacher_id: ''
  });
  const [loading, setLoading] = useState(false);
  const [message, setMessage] = useState('');
  const [error, setError] = useState('');

  useEffect(() => {
    fetchClasses();
    fetchTeachers();
  }, []);

  const fetchClasses = async () => {
    try {
      const res = await api.get('/director/classes');
      setClasses(res.data);
    } catch (err) {
      console.error('Ошибка загрузки классов:', err);
    }
  };

  const fetchTeachers = async () => {
    try {
      const res = await api.get('/director/teachers');
      setTeachers(res.data);
    } catch (err) {
      console.error('Ошибка загрузки учителей:', err);
    }
  };

  const handleCreateClass = async (e) => {
    e.preventDefault();
    setLoading(true);
    setError('');
    setMessage('');
    try {
      await api.post('/director/class', newClass);
      setMessage('Класс создан!');
      setShowModal(false);
      fetchClasses();
      setNewClass({ grade: 1, teacher_id: '' });
    } catch (err) {
      setError(err.response?.data?.error || 'Ошибка создания класса');
    } finally {
      setLoading(false);
    }
  };

  const handlePromote = async (classId) => {
    if (!window.confirm('Перевести учеников в следующий класс?')) return;
    setLoading(true);
    try {
      const res = await api.post('/director/promote', { currentClassId: classId });
      setMessage(res.data.message);
      fetchClasses();
    } catch (err) {
      setError(err.response?.data?.message || 'Ошибка перевода');
    } finally {
      setLoading(false);
    }
  };

  const getTeacherName = (cls) => {
    if (cls.teacher_id && cls.last_name) {
      return `${cls.last_name} ${cls.first_name}`;
    }
    return 'Не назначен';
  };

  return (
    <Container className="mt-4">
      <h3>Управление классами</h3>
      
      {message && <Alert variant="success" onClose={() => setMessage('')} dismissible>{message}</Alert>}
      {error && <Alert variant="danger" onClose={() => setError('')} dismissible>{error}</Alert>}
      
      <Button variant="primary" onClick={() => setShowModal(true)} className="mb-3">
        Создать класс
      </Button>
      
      <Table striped bordered hover>
        <thead>
          <tr>
            <th>Класс</th>
            <th>Классный руководитель</th>
            <th>Учебный год</th>
            <th>Действия</th>
          </tr>
        </thead>
        <tbody>
          {classes.map(cls => (
            <tr key={cls.id}>
              <td><strong>{cls.grade}</strong></td>
              <td>{getTeacherName(cls)}</td>
              <td>{cls.academic_year}</td>
              <td>
                <Button 
                  variant="warning" 
                  size="sm" 
                  onClick={() => handlePromote(cls.id)}
                  disabled={cls.grade >= 9}
                >
                  Перевести в следующий класс
                </Button>
                {cls.grade >= 9 && (
                  <span className="text-muted ms-2">Выпускной класс</span>
                )}
              </td>
            </tr>
          ))}
        </tbody>
      </Table>

      {/* Модальное окно создания класса */}
      <Modal show={showModal} onHide={() => setShowModal(false)}>
        <Modal.Header closeButton>
          <Modal.Title>Создать класс</Modal.Title>
        </Modal.Header>
        <Modal.Body>
          <Form onSubmit={handleCreateClass}>
            <Form.Group className="mb-3">
              <Form.Label>Номер класса</Form.Label>
              <Form.Select
                value={newClass.grade}
                onChange={(e) => setNewClass({ ...newClass, grade: parseInt(e.target.value) })}
                required
              >
                {[1,2,3,4,5,6,7,8,9].map(g => (
                  <option key={g} value={g}>{g}</option>
                ))}
              </Form.Select>
            </Form.Group>
            
            <Form.Group className="mb-3">
              <Form.Label>Классный руководитель</Form.Label>
              <Form.Select
                value={newClass.teacher_id}
                onChange={(e) => setNewClass({ ...newClass, teacher_id: e.target.value || null })}
              >
                <option value="">Не назначен</option>
                {teachers.map(t => (
                  <option key={t.id} value={t.id}>
                    {t.last_name} {t.first_name} {t.middle_name}
                  </option>
                ))}
              </Form.Select>
            </Form.Group>
            
            <Button type="submit" variant="primary" disabled={loading}>
              {loading ? 'Создание...' : 'Создать'}
            </Button>
          </Form>
        </Modal.Body>
      </Modal>
    </Container>
  );
};

export default ClassManager;
